#!/usr/bin/env python3
"""
Automatisk generert av generate.py (adminusers) - IKKE rediger denne filen direkte.

Runde 2: admin-brukerhandtering - rediger (navn/e-post/rolle/passord) og slett
eksisterende admin-brukere fra Administratorer-fanen, med sikkerhetsnett mot a
endre/slette seg selv eller fjerne siste fulle administrator.

Idempotent: hvert steg hopper over seg selv hvis allerede gjort.
Kjor fra prosjektroten: python3 scripts/deploy_admin_users.py
"""
import pathlib
import subprocess
import sys

ROOT = pathlib.Path(__file__).resolve().parent.parent

ok = True

def apply_edit(path, old, new, marker, label):
    global ok
    text = path.read_text()
    if marker in text:
        print(f"[already done] {label}")
        return
    if text.count(old) != 1:
        print(f"[SKIPPED - ikke funnet/entydig] {label}")
        ok = False
        return
    path.write_text(text.replace(old, new, 1))
    print(f"[OK] {label}")

def write_full(path, content, marker, label):
    global ok
    if path.exists() and marker in path.read_text():
        print(f"[already done] {label}")
        return
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(content)
    print(f"[OK] {label}")

