apply_edit(TYPES_PATH, '  listAdminUsers(): Promise<AdminUser[]>;\n  /** Oppdaterer passordet til en admin-bruker. Kalleren har allerede verifisert nåværende passord. */\n  updateAdminPassword(id: string, passwordHash: string, passwordSalt: string): Promise<void>;', '  listAdminUsers(): Promise<AdminUser[]>;\n  /** Oppdaterer passordet til en admin-bruker. Kalleren har allerede verifisert nåværende passord. */\n  updateAdminPassword(id: string, passwordHash: string, passwordSalt: string): Promise<void>;\n\n  /**\n   * Endrer navn/e-post/rolle på en eksisterende admin-bruker (brukt fra\n   * "Rediger" i Administratorer-fanen, se app/admin/account/AccountSettings.tsx).\n   * Kalleren (API-ruten i app/api/admin/account/users/[id]/route.ts) har\n   * allerede sjekket e-post-kollisjon, at man ikke endrer sin egen rolle, og\n   * "siste fulle administrator"-regelen – dette laget utfører bare selve\n   * endringen. Kaster hvis brukeren ikke finnes.\n   */\n  updateAdminUser(id: string, patch: { name?: string; email?: string; role?: AdminRole }): Promise<AdminUser>;\n\n  /**\n   * Sletter en admin-bruker. Kalleren har allerede sjekket at det ikke er\n   * brukeren selv, og at det ikke er siste fulle administrator. Kaster hvis\n   * brukeren ikke finnes.\n   */\n  deleteAdminUser(id: string): Promise<void>;', 'updateAdminUser(id: string, patch:', 'types-repo-method')

LOCAL_PATH = ROOT / 'lib' / 'db' / 'local.ts'
apply_edit(LOCAL_PATH, '  async updateAdminPassword(id, passwordHash, passwordSalt) {\n    return withLock(async () => {\n      const db = await loadDb();\n      const user = db.adminUsers.find((u) => u.id === id);\n      if (!user) throw new Error("Fant ingen admin-bruker med denne iden.");\n      user.passwordHash = passwordHash;\n      user.passwordSalt = passwordSalt;\n      await saveDb(db);\n    });\n  },\n\n  async getSetting(key) {', '  async updateAdminPassword(id, passwordHash, passwordSalt) {\n    return withLock(async () => {\n      const db = await loadDb();\n      const user = db.adminUsers.find((u) => u.id === id);\n      if (!user) throw new Error("Fant ingen admin-bruker med denne iden.");\n      user.passwordHash = passwordHash;\n      user.passwordSalt = passwordSalt;\n      await saveDb(db);\n    });\n  },\n\n  async updateAdminUser(id, patch) {\n    return withLock(async () => {\n      const db = await loadDb();\n      const user = db.adminUsers.find((u) => u.id === id);\n      if (!user) throw new Error("Fant ingen admin-bruker med denne iden.");\n      if (patch.name !== undefined) user.name = patch.name;\n      if (patch.email !== undefined) user.email = patch.email;\n      if (patch.role !== undefined) user.role = patch.role;\n      await saveDb(db);\n      return normalizeAdminUser(user);\n    });\n  },\n\n  async deleteAdminUser(id) {\n    return withLock(async () => {\n      const db = await loadDb();\n      const exists = db.adminUsers.some((u) => u.id === id);\n      if (!exists) throw new Error("Fant ingen admin-bruker med denne iden.");\n      db.adminUsers = db.adminUsers.filter((u) => u.id !== id);\n      await saveDb(db);\n    });\n  },\n\n  async getSetting(key) {', 'async deleteAdminUser(id) {', 'local-admin-methods')

SUPABASE_PATH = ROOT / 'lib' / 'db' / 'supabase.ts'
apply_edit(SUPABASE_PATH, '  async updateAdminPassword(id, passwordHash, passwordSalt) {\n    const supabase = getSupabaseAdmin();\n    const { error } = await supabase\n      .from("admin_users")\n      .update({ password_hash: passwordHash, password_salt: passwordSalt })\n      .eq("id", id);\n    if (error) throw new Error(`Kunne ikke oppdatere passord: ${error.message}`);\n  },\n\n  async getSetting(key) {', '  async updateAdminPassword(id, passwordHash, passwordSalt) {\n    const supabase = getSupabaseAdmin();\n    const { error } = await supabase\n      .from("admin_users")\n      .update({ password_hash: passwordHash, password_salt: passwordSalt })\n      .eq("id", id);\n    if (error) throw new Error(`Kunne ikke oppdatere passord: ${error.message}`);\n  },\n\n  async updateAdminUser(id, patch) {\n    const supabase = getSupabaseAdmin();\n    // Satt sammen med spredning (ikke en mellomliggende Record<string,string>-\n    // variabel) slik at TypeScript kan sjekke resultatet direkte mot den\n    // håndskrevne admin_users-Update-typen i database.types.ts – samme\n    // årsak som typecheck-feilen opponent_name ga i turneringsrunden.\n    const { data, error } = await supabase\n      .from("admin_users")\n      .update({\n        ...(patch.name !== undefined ? { name: patch.name } : {}),\n        ...(patch.email !== undefined ? { email: patch.email.toLowerCase() } : {}),\n        ...(patch.role !== undefined ? { role: patch.role } : {}),\n      })\n      .eq("id", id)\n      .select()\n      .single();\n    if (error) throw new Error(`Kunne ikke oppdatere admin-bruker: ${error.message}`);\n    const row = data as {\n      id: string;\n      email: string;\n      name: string;\n      password_hash: string;\n      password_salt: string;\n      role: string | null;\n      created_at: string;\n    };\n    return {\n      id: row.id,\n      email: row.email,\n      name: row.name,\n      passwordHash: row.password_hash,\n      passwordSalt: row.password_salt,\n      role: (row.role as AdminRole | null) ?? "full",\n      createdAt: row.created_at,\n    };\n  },\n\n  async deleteAdminUser(id) {\n    const supabase = getSupabaseAdmin();\n    const { error } = await supabase.from("admin_users").delete().eq("id", id);\n    if (error) throw new Error(`Kunne ikke slette admin-bruker: ${error.message}`);\n  },\n\n  async getSetting(key) {', 'async deleteAdminUser(id) {', 'sb-admin-methods')

