apply_edit(ACCOUNTSETTINGS_PATH, '  const [ownRole, setOwnRole] = useState<AdminRole | null>(null);', '  const [ownRole, setOwnRole] = useState<AdminRole | null>(null);\n  /** Egen bruker-id (session.sub, se /api/admin/me) - brukes til å skjule Rediger/Slett på egen rad under. */\n  const [ownId, setOwnId] = useState<string | null>(null);', 'const [ownId, setOwnId] = useState<string | null>(null);', 'as-ownid-state')
apply_edit(ACCOUNTSETTINGS_PATH, '  useEffect(() => {\n    fetch("/api/admin/me", { cache: "no-store" })\n      .then((res) => (res.ok ? (res.json() as Promise<{ role?: AdminRole }>) : null))\n      .then((data) => {\n        const role = data?.role ?? "full";\n        setOwnRole(role);\n        // En begrenset administrator har uansett ikke tilgang til\n        // /api/admin/account/users (se middleware.ts), så det er ingen vits\n        // i å prøve å laste listen for dem.\n        if (role === "full") loadUsers();\n        else setLoadingUsers(false);\n      })\n      .catch(() => {\n        setOwnRole("full");\n        loadUsers();\n      });\n  }, []);', '  useEffect(() => {\n    fetch("/api/admin/me", { cache: "no-store" })\n      .then((res) => (res.ok ? (res.json() as Promise<{ id?: string; role?: AdminRole }>) : null))\n      .then((data) => {\n        const role = data?.role ?? "full";\n        setOwnRole(role);\n        setOwnId(data?.id ?? null);\n        // En begrenset administrator har uansett ikke tilgang til\n        // /api/admin/account/users (se middleware.ts), så det er ingen vits\n        // i å prøve å laste listen for dem.\n        if (role === "full") loadUsers();\n        else setLoadingUsers(false);\n      })\n      .catch(() => {\n        setOwnRole("full");\n        loadUsers();\n      });\n  }, []);', 'setOwnId(data?.id ?? null);', 'as-fetch-me')
apply_edit(ACCOUNTSETTINGS_PATH, '  const [newEmail, setNewEmail] = useState("");\n  const [newName, setNewName] = useState("");\n  const [newUserRole, setNewUserRole] = useState<AdminRole>("full");\n  const [newUserPassword, setNewUserPassword] = useState("");\n  const [newUserPasswordConfirm, setNewUserPasswordConfirm] = useState("");\n  const [creatingUser, setCreatingUser] = useState(false);\n  const [createMessage, setCreateMessage] = useState<{ ok: boolean; text: string } | null>(null);', '  const [newEmail, setNewEmail] = useState("");\n  const [newName, setNewName] = useState("");\n  const [newUserRole, setNewUserRole] = useState<AdminRole>("full");\n  const [newUserPassword, setNewUserPassword] = useState("");\n  const [newUserPasswordConfirm, setNewUserPasswordConfirm] = useState("");\n  const [creatingUser, setCreatingUser] = useState(false);\n  const [createMessage, setCreateMessage] = useState<{ ok: boolean; text: string } | null>(null);\n\n  // --- Rediger/slett en EKSISTERENDE admin-bruker (aldri egen rad, se ownId) ---\n  const [editingId, setEditingId] = useState<string | null>(null);\n  const [editName, setEditName] = useState("");\n  const [editEmail, setEditEmail] = useState("");\n  const [editRole, setEditRole] = useState<AdminRole>("full");\n  const [editPassword, setEditPassword] = useState("");\n  const [savingEdit, setSavingEdit] = useState(false);\n  const [editMessage, setEditMessage] = useState<{ ok: boolean; text: string } | null>(null);\n  const [deletingId, setDeletingId] = useState<string | null>(null);\n\n  function startEdit(u: AdminUserRow) {\n    setEditingId(u.id);\n    setEditName(u.name);\n    setEditEmail(u.email);\n    setEditRole(u.role);\n    setEditPassword("");\n    setEditMessage(null);\n  }\n\n  function cancelEdit() {\n    setEditingId(null);\n    setEditMessage(null);\n  }\n\n  async function handleSaveEdit(e: FormEvent, id: string) {\n    e.preventDefault();\n    setSavingEdit(true);\n    setEditMessage(null);\n    try {\n      const body: { name: string; email: string; role: AdminRole; password?: string } = {\n        name: editName,\n        email: editEmail,\n        role: editRole,\n      };\n      if (editPassword.trim().length > 0) body.password = editPassword;\n\n      const res = await fetch(`/api/admin/account/users/${id}`, {\n        method: "PATCH",\n        headers: { "Content-Type": "application/json" },\n        body: JSON.stringify(body),\n      });\n      const data = (await res.json()) as { error?: string };\n\n      if (!res.ok) {\n        setEditMessage({ ok: false, text: data.error ?? "Kunne ikke lagre." });\n        return;\n      }\n\n      setEditingId(null);\n      await loadUsers();\n    } catch {\n      setEditMessage({ ok: false, text: "Kunne ikke lagre akkurat nå." });\n    } finally {\n      setSavingEdit(false);\n    }\n  }\n\n  async function handleDeleteUser(u: AdminUserRow) {\n    if (!window.confirm(`Slette admin-brukeren "${u.name}" (${u.email})? Dette kan ikke angres.`)) return;\n\n    setDeletingId(u.id);\n    try {\n      const res = await fetch(`/api/admin/account/users/${u.id}`, { method: "DELETE" });\n      const data = (await res.json().catch(() => ({}))) as { error?: string };\n      if (!res.ok) {\n        window.alert(data.error ?? "Kunne ikke slette brukeren.");\n        return;\n      }\n      await loadUsers();\n    } finally {\n      setDeletingId(null);\n    }\n  }', 'async function handleDeleteUser(u: AdminUserRow) {', 'as-edit-state-and-handlers')
apply_edit(ACCOUNTSETTINGS_PATH, '              {users.map((u) => (\n                <div key={u.id} className={styles.userRow}>\n                  <div>\n                    <strong>{u.name}</strong>\n                    <div className={styles.bookingMeta}>{u.email}</div>\n                  </div>\n                  <div className={styles.bookingMeta}>\n                    {ROLE_LABEL[u.role]} &middot; lagt til {formatOslo(u.createdAt, "d. MMM yyyy")}\n                  </div>\n                </div>\n              ))}', '              {users.map((u) => (\n                <div key={u.id} className={styles.userRow}>\n                  {editingId === u.id ? (\n                    <form onSubmit={(e) => handleSaveEdit(e, u.id)} className={styles.form} style={{ width: "100%" }}>\n                      <div className={styles.formRow}>\n                        <label htmlFor={`edit-name-${u.id}`}>Navn</label>\n                        <input\n                          id={`edit-name-${u.id}`}\n                          type="text"\n                          required\n                          minLength={2}\n                          value={editName}\n                          onChange={(e) => setEditName(e.target.value)}\n                        />\n                      </div>\n                      <div className={styles.formRow}>\n                        <label htmlFor={`edit-email-${u.id}`}>E-post</label>\n                        <input\n                          id={`edit-email-${u.id}`}\n                          type="email"\n                          required\n                          value={editEmail}\n                          onChange={(e) => setEditEmail(e.target.value)}\n                          autoComplete="off"\n                        />\n                      </div>\n                      <div className={styles.formRow}>\n                        <label htmlFor={`edit-role-${u.id}`}>Rolle</label>\n                        <select\n                          id={`edit-role-${u.id}`}\n                          value={editRole}\n                          onChange={(e) => setEditRole(e.target.value as AdminRole)}\n                        >\n                          <option value="full">Full administrator</option>\n                          <option value="bookings_only">Begrenset (kun Bookinger)</option>\n                        </select>\n                      </div>\n                      <div className={styles.formRow}>\n                        <label htmlFor={`edit-password-${u.id}`}>Nytt passord (valgfritt)</label>\n                        <input\n                          id={`edit-password-${u.id}`}\n                          type="password"\n                          minLength={8}\n                          value={editPassword}\n                          onChange={(e) => setEditPassword(e.target.value)}\n                          autoComplete="new-password"\n                          placeholder="La stå tom for å ikke endre"\n                        />\n                      </div>\n\n                      {editMessage && (\n                        <p className={editMessage.ok ? styles.success : styles.error}>{editMessage.text}</p>\n                      )}\n\n                      <div style={{ display: "flex", gap: 8 }}>\n                        <button type="submit" className={styles.submitButton} disabled={savingEdit}>\n                          {savingEdit ? "Lagrer …" : "Lagre"}\n                        </button>\n                        <button\n                          type="button"\n                          className={styles.secondaryButton}\n                          onClick={cancelEdit}\n                          disabled={savingEdit}\n                        >\n                          Avbryt\n                        </button>\n                      </div>\n                    </form>\n                  ) : (\n                    <>\n                      <div>\n                        <strong>{u.name}</strong>\n                        <div className={styles.bookingMeta}>{u.email}</div>\n                      </div>\n                      <div className={styles.bookingMeta}>\n                        {ROLE_LABEL[u.role]} &middot; lagt til {formatOslo(u.createdAt, "d. MMM yyyy")}\n                      </div>\n                      {u.id !== ownId && (\n                        <div style={{ display: "flex", gap: 8 }}>\n                          <button type="button" className={styles.secondaryButton} onClick={() => startEdit(u)}>\n                            Rediger\n                          </button>\n                          <button\n                            type="button"\n                            className={styles.dangerButton}\n                            disabled={deletingId === u.id}\n                            onClick={() => handleDeleteUser(u)}\n                          >\n                            {deletingId === u.id ? "Sletter …" : "Slett"}\n                          </button>\n                        </div>\n                      )}\n                    </>\n                  )}\n                </div>\n              ))}', 'editingId === u.id ? (', 'as-userrow-jsx')

write_full(ROOT / 'app' / 'api' / 'admin' / 'account' / 'users' / '[id]' / 'route.ts', 'import { NextRequest, NextResponse } from "next/server";\nimport { getRepository } from "@/lib/db";\nimport { hashPassword } from "@/lib/auth/password";\nimport { SESSION_COOKIE_NAME, verifySessionCookieValue } from "@/lib/auth/session";\nimport type { AdminRole } from "@/lib/db/types";\n\nexport const dynamic = "force-dynamic";\n\nconst VALID_ROLES: AdminRole[] = ["full", "bookings_only"];\n\ninterface PatchBody {\n  name?: string;\n  email?: string;\n  role?: string;\n  /** Valgfritt – satt administrator kan sette et nytt passord DIREKTE for en\n   * ANNEN bruker her (uten å kjenne det gamle). Bytte av EGET passord skjer\n   * fortsatt via /api/admin/account/password (krever nåværende passord). */\n  password?: string;\n}\n\n/**\n * PATCH  /api/admin/account/users/:id – endre navn/e-post/rolle, og evt.\n *        sett et nytt passord direkte på en ANNEN admin-bruker.\n * DELETE /api/admin/account/users/:id – slett admin-brukeren.\n *\n * Beskyttet av middleware.ts på samme måte som /api/admin/account/users\n * (GET/POST) – IKKE i noen av BOOKINGS_ONLY_ALLOWED_*-listene der, så en\n * begrenset administrator nektes automatisk, uten at middleware.ts trenger\n * noen endring for denne nye undersiden.\n *\n * To sikkerhetsnett som gjelder BÅDE endring av rolle og sletting:\n *  1) Man kan ikke endre sin EGEN rolle eller slette sin EGEN bruker herfra\n *     (be en annen full administrator om det) – forhindrer at man ved et\n *     uhell låser seg selv ute, eller sletter kontoen man er innlogget med.\n *  2) Det må alltid finnes minst én "full" administrator igjen etterpå –\n *     forhindrer at alle admin-brukere ender opp begrenset (eller slettet),\n *     uten noen som kan rette det opp igjen.\n *\n * NB: rollen ligger signert i selve sesjonscookien (se lib/auth/session.ts)\n * og sjekkes IKKE på nytt mot databasen for hver forespørsel (se\n * middleware.ts) – endres en INNLOGGET admin sin rolle her, beholder\n * personen sin gamle rolle til cookien fornyes (neste innlogging, senest om\n * 7 dager).\n */\nasync function requireSession(request: NextRequest) {\n  return verifySessionCookieValue(request.cookies.get(SESSION_COOKIE_NAME)?.value);\n}\n\nexport async function PATCH(request: NextRequest, { params }: { params: Promise<{ id: string }> }) {\n  const session = await requireSession(request);\n  if (!session) return NextResponse.json({ error: "Ikke innlogget." }, { status: 401 });\n\n  const { id } = await params;\n\n  let body: PatchBody;\n  try {\n    body = (await request.json()) as PatchBody;\n  } catch {\n    return NextResponse.json({ error: "Ugyldig forespørsel." }, { status: 400 });\n  }\n\n  const repo = await getRepository();\n  const users = await repo.listAdminUsers();\n  const target = users.find((u) => u.id === id);\n  if (!target) {\n    return NextResponse.json({ error: "Fant ingen admin-bruker med denne iden." }, { status: 404 });\n  }\n\n  const patch: { name?: string; email?: string; role?: AdminRole } = {};\n\n  if (body.name !== undefined) {\n    const name = body.name.trim();\n    if (!name || name.length < 2) {\n      return NextResponse.json({ error: "Skriv inn navnet til personen." }, { status: 400 });\n    }\n    patch.name = name;\n  }\n\n  if (body.email !== undefined) {\n    const email = body.email.trim().toLowerCase();\n    if (!email || !email.includes("@")) {\n      return NextResponse.json({ error: "Skriv inn en gyldig e-postadresse." }, { status: 400 });\n    }\n    const existing = await repo.getAdminByEmail(email);\n    if (existing && existing.id !== id) {\n      return NextResponse.json(\n        { error: "Det finnes allerede en admin-bruker med denne e-posten." },\n        { status: 409 }\n      );\n    }\n    patch.email = email;\n  }\n\n  if (body.role !== undefined) {\n    const role = body.role.trim() as AdminRole;\n    if (!VALID_ROLES.includes(role)) {\n      return NextResponse.json({ error: "Ugyldig rolle." }, { status: 400 });\n    }\n    if (target.id === session.sub) {\n      return NextResponse.json(\n        { error: "Du kan ikke endre din egen rolle. Be en annen full administrator om det." },\n        { status: 400 }\n      );\n    }\n    if (target.role === "full" && role !== "full") {\n      const remainingFullAdmins = users.filter((u) => u.role === "full" && u.id !== id).length;\n      if (remainingFullAdmins === 0) {\n        return NextResponse.json(\n          { error: "Dette er den siste fulle administratoren. Gjør en annen bruker til full administrator først." },\n          { status: 400 }\n        );\n      }\n    }\n    patch.role = role;\n  }\n\n  if (Object.keys(patch).length > 0) {\n    await repo.updateAdminUser(id, patch);\n  }\n\n  if (body.password !== undefined && body.password !== "") {\n    if (body.password.length < 8) {\n      return NextResponse.json({ error: "Det nye passordet bør være minst 8 tegn." }, { status: 400 });\n    }\n    const { hash, salt } = await hashPassword(body.password);\n    await repo.updateAdminPassword(id, hash, salt);\n  }\n\n  const updatedUsers = await repo.listAdminUsers();\n  const updated = updatedUsers.find((u) => u.id === id);\n  return NextResponse.json({\n    ok: true,\n    user: updated\n      ? { id: updated.id, name: updated.name, email: updated.email, role: updated.role, createdAt: updated.createdAt }\n      : null,\n  });\n}\n\nexport async function DELETE(request: NextRequest, { params }: { params: Promise<{ id: string }> }) {\n  const session = await requireSession(request);\n  if (!session) return NextResponse.json({ error: "Ikke innlogget." }, { status: 401 });\n\n  const { id } = await params;\n\n  if (id === session.sub) {\n    return NextResponse.json(\n      { error: "Du kan ikke slette din egen bruker. Be en annen full administrator om det." },\n      { status: 400 }\n    );\n  }\n\n  const repo = await getRepository();\n  const users = await repo.listAdminUsers();\n  const target = users.find((u) => u.id === id);\n  if (!target) {\n    return NextResponse.json({ error: "Fant ingen admin-bruker med denne iden." }, { status: 404 });\n  }\n\n  if (target.role === "full") {\n    const remainingFullAdmins = users.filter((u) => u.role === "full" && u.id !== id).length;\n    if (remainingFullAdmins === 0) {\n      return NextResponse.json(\n        { error: "Dette er den siste fulle administratoren og kan ikke slettes." },\n        { status: 400 }\n      );\n    }\n  }\n\n  await repo.deleteAdminUser(id);\n  return NextResponse.json({ ok: true });\n}\n', 'export async function DELETE', 'ny fil: app/api/admin/account/users/[id]/route.ts')

if not ok:
    print("\nEtt eller flere steg feilet - avbryter FOR typecheck (ingenting antas trygt).")
    sys.exit(1)

print("\nKjorer typecheck ...")
result = subprocess.run(["npm", "run", "typecheck"], cwd=ROOT)
if result.returncode == 0:
    print("\nTYPECHECK OK")
else:
    print("\nTYPECHECK FEILET")
    sys.exit(1)
